1349	async function applyPalworld(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
1350	  const envMap = await readContainerEnv(conn, PALWORLD_CONTAINER);
1351	  if (!envMap) {
1352	    return { ok: false, applied: [], notes: [`Could not find the "${PALWORLD_CONTAINER}" container — nothing was changed.`] };
1353	  }
1354	
1355	  const applied: string[] = [];
1356	  for (const [key, val] of Object.entries(v)) {
1357	    const mapping = PALWORLD_ENV_MAP[key];
1358	    if (!mapping || val == null) continue;
1359	    envMap.set(mapping.env, mapping.format(val));
1360	    applied.push(key);
1361	  }
1362	  if (applied.length === 0) {
1363	    return { ok: true, applied: [], notes: ["No changes to apply."] };
1364	  }
1365	
1366	  await writeEnvFile(conn, sftp, "/root/palworld.env", envMap);
1367	
1368	  // Ports + volume exactly as prisma/catalog.ts provisions them, except RCON,
1369	  // which is bound to loopback rather than 0.0.0.0 — the platform's own RCON
1370	  // tunnels to 127.0.0.1 over SSH, so nothing needs it published.
1371	  const res = await recreateGameContainer(conn, {
1372	    family: "palworld",
1373	    container: PALWORLD_CONTAINER,
1374	    runFlags: "-p 8211:8211/udp -p 127.0.0.1:25575:25575/tcp -v /opt/palworld:/palworld --env-file /root/palworld.env",
1375	    image: "thijsvanloef/palworld-server-docker",
1376	  });
1377	  if (!res.ok) return { ok: false, applied: [], notes: [res.note] };
1378	
1379	  return {
1380	    ok: true,
1381	    applied: [`Applied ${applied.length} setting(s): ${applied.join(", ")}.`],
1382	    notes: ["Your server restarted briefly to apply these — any connected players were disconnected and can rejoin now."],
1383	  };
1384	}
1385	
1386	const BEDROCK_CONTAINER = "bedrock";
1387	
1388	/**
1389	 * Schema field key -> itzg/docker-minecraft-bedrock-server env var name +
1390	 * value formatting. Same rationale as PALWORLD_ENV_MAP above: this image
1391	 * regenerates its config from these env vars on every boot, so the ONLY way
1392	 * to change a setting for real is to recreate the container with a new
1393	 * environment — never editing a config file in place, which the next boot
1394	 * would just overwrite anyway.
1395	 *
1396	 * Verified against the image's own documented env vars (its README), not
1397	 * guessed from the field's schema key — see BEDROCK's own schema comment in
1398	 * lib/game-config.ts for why a generic 1:1 rename would be wrong here
1399	 * (`max-players` -> `MAX_PLAYERS`, `white-list` -> `ALLOW_LIST`, etc., not a
1400	 * literal case-fold of the field key).
1401	 */
1402	const BEDROCK_ENV_MAP: Record<string, { env: string; format: (v: string | number | boolean) => string }> = {
1403	  VERSION: { env: "VERSION", format: (v) => String(v) },
1404	  gamemode: { env: "GAMEMODE", format: (v) => String(v) },
1405	  difficulty: { env: "DIFFICULTY", format: (v) => String(v) },
1406	  "max-players": { env: "MAX_PLAYERS", format: (v) => String(v) },
1407	  "allow-cheats": { env: "ALLOW_CHEATS", format: (v) => bool(v) },
1408	  "level-name": { env: "LEVEL_NAME", format: (v) => String(v) },
1409	  "level-seed": { env: "LEVEL_SEED", format: (v) => String(v) },
1410	  "online-mode": { env: "ONLINE_MODE", format: (v) => bool(v) },
1411	  "view-distance": { env: "VIEW_DISTANCE", format: (v) => String(v) },
1412	  "white-list": { env: "ALLOW_LIST", format: (v) => bool(v) },
1413	};
1414	
1415	async function applyBedrock(conn: Client, sftp: SFTPWrapper, v: Values): Promise<ApplyOutcome> {
1416	  const envMap = await readContainerEnv(conn, BEDROCK_CONTAINER);
1417	  if (!envMap) {
1418	    return { ok: false, applied: [], notes: [`Could not find the "${BEDROCK_CONTAINER}" container — nothing was changed.`] };
1419	  }
1420	
1421	  const applied: string[] = [];
1422	  for (const [key, val] of Object.entries(v)) {
1423	    const mapping = BEDROCK_ENV_MAP[key];
1424	    if (!mapping || val == null) continue;
1425	    // A blank level-seed means "let the server pick one" (the schema's own
1426	    // default) — setting LEVEL_SEED="" is not the same as leaving it unset
1427	    // for every image, so skip it entirely rather than risk forcing an
1428	    // empty-string seed the image might treat literally.
1429	    if (key === "level-seed" && String(val).trim().length === 0) continue;
1430	    envMap.set(mapping.env, mapping.format(val));
1431	    applied.push(key);
1432	  }
1433	  if (applied.length === 0) {
1434	    return { ok: true, applied: [], notes: ["No changes to apply."] };
1435	  }
