import { db } from "/opt/nxeon/lib/db";
import { withServerSsh } from "/opt/nxeon/lib/ssh-exec";

async function execRemote(conn: any, cmd: string): Promise<{ code: number; stdout: string; stderr: string }> {
  return new Promise((resolve, reject) => {
    conn.exec(cmd, (err: any, stream: any) => {
      if (err) return reject(err);
      let stdout = "";
      let stderr = "";
      stream.on("data", (d: Buffer) => (stdout += d.toString()));
      stream.stderr.on("data", (d: Buffer) => (stderr += d.toString()));
      stream.on("close", (code: number) => resolve({ code, stdout, stderr }));
    });
  });
}

async function main() {
  const server = await db.server.findUnique({
    where: { id: "cmuljxlr91qs7hl5tmhigoqy9" },
    include: { node: true, dedicatedIp: true },
