import { db } from "/root/nxeon-worktrees/palworld-crossplay/lib/db";
import { validateConfig, GAME_CONFIG_VERSION } from "/root/nxeon-worktrees/palworld-crossplay/lib/game-config";
import { applyRealConfig } from "/root/nxeon-worktrees/palworld-crossplay/worker/game-config";
import { SANDBOX } from "/root/nxeon-worktrees/palworld-crossplay/lib/sandbox";

const SERVER_ID = "cmuljxlr91qs7hl5tmhigoqy9"; // palworld-0y55qe / Misty's Casual Veil

async function main() {
  const server = await db.server.findUnique({
    where: { id: SERVER_ID },
    include: { dedicatedIp: true, node: true },
  });
  if (!server) throw new Error("server not found");
  console.log("Before gameConfig:", JSON.stringify(server.gameConfig));

  const existing = (server.gameConfig as Record<string, unknown> | null) ?? {};
  const desiredLabel = server.label?.trim() || "Nxeon Palworld Server";
  const rawUpdated = {
    ...existing,
    "community-servers": true,
    "server-name": desiredLabel,
  };

  const valid = validateConfig("palworld", rawUpdated);
  if (!valid.ok) throw new Error("validateConfig failed: " + valid.error);
  console.log("Validated values to apply:", JSON.stringify(valid.values, null, 2));

  // Persist exactly like lib/actions-game-config.ts's real save path does
  // (clean validated values, no markers yet).
  await db.server.update({
    where: { id: server.id },
    data: { gameConfig: valid.values as any },
  });

  const outcome = await applyRealConfig(server as any, "palworld", valid.values);
  console.log("Apply outcome:", JSON.stringify(outcome, null, 2));

  const marker = {
    _appliedVariant: server.gameVariant ?? "vanilla",
    _appliedAt: new Date().toISOString(),
    _configVersion: GAME_CONFIG_VERSION,
    _sandbox: SANDBOX,
    _real: true,
    _realOk: outcome.ok,
  };
  await db.server.update({
    where: { id: server.id },
    data: { gameConfig: { ...(valid.values as any), ...marker } as any },
  });

  const after = await db.server.findUnique({ where: { id: SERVER_ID } });
  console.log("After gameConfig:", JSON.stringify(after?.gameConfig, null, 2));
}

main().then(() => process.exit(0)).catch((e) => { console.error("ERROR", e); process.exit(1); });

